{
  "passages": [
    {
      "id": "m76",
      "about_topic": true,
      "says": "rule: do not pass a vehicle stopped at a crosswalk, with reason"
    },
    {
      "id": "m54",
      "about_topic": true,
      "says": "fact: cyclists can use any part of the lane if necessary for safety, introducing a list of purposes"
    },
    {
      "id": "m55",
      "about_topic": true,
      "says": "fact item: a purpose is to discourage passing where the lane is too narrow to be shared safely"
    },
    {
      "id": "m59",
      "about_topic": true,
      "says": "figure: Diagram 2-11 referenced by the 1 m cyclist-passing rule"
    },
    {
      "id": "m56",
      "about_topic": true,
      "says": "legal rule: maintain a minimum distance of 1 m when passing a cyclist where practical"
    },
    {
      "id": "m57",
      "about_topic": true,
      "says": "penalty: failure to maintain the 1 m distance may result in a fine and 2 demerit points"
    },
    {
      "id": "m58",
      "about_topic": true,
      "says": "advice: change lanes to pass a cyclist whenever possible"
    },
    {
      "id": "m60",
      "about_topic": true,
      "says": "advice: do not sound the horn unnecessarily when passing a cyclist; if using the horn is felt necessary, tap it quickly and lightly from some distance"
    },
    {
      "id": "m96",
      "about_topic": true,
      "says": "advice: check for a passing cyclist before opening a door of a parked vehicle"
    },
    {
      "id": "m65",
      "about_topic": true,
      "says": "advice: do not cut in front closely of a large vehicle; allow more room when passing a large vehicle"
    },
    {
      "id": "m66",
      "about_topic": true,
      "says": "fact: a large vehicle can create turbulence that may affect control when passing"
    },
    {
      "id": "m69",
      "about_topic": true,
      "says": "advice: stay well back from farm machinery; do not pass until safe"
    },
    {
      "id": "m70",
      "about_topic": true,
      "says": "advice: maintain a safe following distance from a horse-drawn vehicle; only pass when safe"
    },
    {
      "id": "m71",
      "about_topic": true,
      "says": "advice: give as much distance as possible when passing a horse-drawn vehicle, with reason"
    }
  ],
  "statements": [
    {
      "id": "s1",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Do not\")",
      "text": "a driver SHOULD NOT pass a vehicle stopped at a crosswalk BECAUSE a stopped vehicle may be a clue that a pedestrian is crossing",
      "sources": [
        {
          "id": "m76",
          "quote": "Do not pass a vehicle stopped at a crosswalk. A stopped vehicle may be a clue that a pedestrian is crossing."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "s2",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT a cyclist can use any part of the lane if [?necessary for safety], such as to discourage passing where the lane is [?too narrow] to be shared [?safely]",
      "sources": [
        {
          "id": "m54",
          "quote": "However, they can use any part of the lane if necessary for safety, such as to:"
        },
        {
          "id": "m55",
          "quote": "Discourage passing where the lane is too narrow to be shared safely"
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "necessary for safety",
          "note": "No test is given for when using any part of the lane is necessary for safety."
        },
        {
          "code": "J",
          "span": "too narrow",
          "note": "No width measure is given for when a lane is too narrow to be shared."
        },
        {
          "code": "J",
          "span": "safely",
          "note": "No measure is given for safe lane sharing."
        }
      ],
      "links": [],
      "note": "Combined the lead sentence and its list item; \"can\" is treated as a description of what a cyclist can do, not as a driver rule."
    },
    {
      "id": "s3",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"must\")",
      "text": "a driver of a motor vehicle MUST maintain a minimum distance of 1 m between the driver's vehicle and the cyclist WHEN the driver is passing a cyclist AND maintaining the distance is [?practical] IF VIOLATED a fine and 2 additional demerit points may result",
      "sources": [
        {
          "id": "m56",
          "quote": "When passing a cyclist, drivers of motor vehicles must maintain a minimum distance of one metre, where practical between their vehicle and the cyclist."
        },
        {
          "id": "m57",
          "quote": "(See Diagram 2-11.) Failure to do so may result in a fine and an additional two demerit points on the driver’s record."
        },
        {
          "id": "m59",
          "quote": "bike lane adjacent to parking bays"
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "practical",
          "note": "The handbook does not define when maintaining 1 m is practical."
        }
      ],
      "links": [],
      "note": "The penalty is kept as a possible consequence with \"may result\". The figure is cited because the passage refers to Diagram 2-11."
    },
    {
      "id": "s4",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "text (\"should\")",
      "text": "a driver SHOULD change lanes to pass a cyclist WHEN the driver is passing a cyclist AND changing lanes is [?possible]",
      "sources": [
        {
          "id": "m58",
          "quote": "Whenever possible, you should change lanes to pass."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "possible",
          "note": "No measure is given for when changing lanes is possible."
        }
      ],
      "links": [],
      "note": "The cyclist is supplied from the heading \"Cyclists\"."
    },
    {
      "id": "s5",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Do not\")",
      "text": "a driver SHOULD NOT sound the horn [?unnecessarily] WHEN the driver is passing a cyclist BECAUSE it may frighten the cyclist and cause the cyclist to lose control",
      "sources": [
        {
          "id": "m60",
          "quote": "Do not sound your horn unnecessarily when you are overtaking a cyclist. It may frighten them and cause them to lose control."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "unnecessarily",
          "note": "No measure is given for when sounding the horn is necessary."
        },
        {
          "code": "V",
          "span": "overtaking",
          "note": "The handbook says overtaking; the statement uses passing for consistency."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "s6",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"tap\")",
      "text": "a driver SHOULD tap the horn [?quickly and lightly] WHEN the driver is passing a cyclist AND the driver [?feels] that the driver must use the horn WHILE the driver is still [?some distance] away from the cyclist",
      "sources": [
        {
          "id": "m60",
          "quote": "Do not sound your horn unnecessarily when you are overtaking a cyclist. It may frighten them and cause them to lose control. If you feel that you must use your horn, tap it quickly and lightly while you are still some distance away from the cyclist."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "quickly and lightly",
          "note": "No measure is given for how quick or light the horn tap must be."
        },
        {
          "code": "J",
          "span": "feels",
          "note": "The condition depends on the driver's subjective feeling."
        },
        {
          "code": "J",
          "span": "some distance",
          "note": "No distance measure is given."
        },
        {
          "code": "V",
          "span": "overtaking",
          "note": "The handbook says overtaking; the statement uses passing for consistency."
        }
      ],
      "links": [],
      "note": "The lower-case must in the condition is part of the driver's feeling, not a legal modal; the force comes from the imperative tap."
    },
    {
      "id": "s7",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"look\", \"check\")",
      "text": "a driver SHOULD look behind AND check the mirrors and blind spots for a passing cyclist WHEN the driver is parked on the side of the roadway AND the driver is about to open a door",
      "sources": [
        {
          "id": "m96",
          "quote": "When parked on the side of the roadway, look behind you and check your mirrors and blind spots for a passing cyclist before opening a door."
        }
      ],
      "flags": [],
      "links": [],
      "note": "\"before opening a door\" is written as \"about to open a door\" because the clause set has no BEFORE."
    },
    {
      "id": "s8",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"do not\")",
      "text": "a driver SHOULD NOT cut in front of a large vehicle [?closely] WHEN the driver is passing a large vehicle BECAUSE it is discourteous, dangerous, and it reduces the space cushion large vehicles require in order to stop [?safely]",
      "sources": [
        {
          "id": "m65",
          "quote": "When passing a large vehicle, do not cut in front closely. Not only is this discourteous, it is dangerous; it reduces the space cushion large vehicles require in order to stop safely."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "closely",
          "note": "No distance measure is given for how close is too close."
        },
        {
          "code": "J",
          "span": "safely",
          "note": "No stopping-distance measure is given."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "s9",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Allow\")",
      "text": "a driver SHOULD allow [?more room] WHEN the driver is passing a large vehicle",
      "sources": [
        {
          "id": "m65",
          "quote": "Allow more room when passing a large vehicle."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "more room",
          "note": "No measure is given for how much extra room is needed."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "s10",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT a large vehicle can create heavy air turbulence due to factors such as air pressure and airflow, and this may affect the driver's ability to control the driver's vehicle WHEN the driver is passing a large vehicle",
      "sources": [
        {
          "id": "m66",
          "quote": "6. Turbulence - Due to various factors such as air pressure and airflow, a large vehicle can create heavy air turbulence. This may affect your ability to control your vehicle when passing a large one."
        }
      ],
      "flags": [],
      "links": [],
      "note": "\"may\" states a possible effect, not a permission."
    },
    {
      "id": "s11",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Stay\")",
      "text": "a driver SHOULD stay [?well back] from farm machinery WHEN the driver is behind farm machinery",
      "sources": [
        {
          "id": "m69",
          "quote": "Stay well back and do not pass until it is safe to do so."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "well back",
          "note": "No distance measure is given."
        },
        {
          "code": "D",
          "span": "behind farm machinery",
          "note": "The situation is not explicitly stated in the sentence; it is inferred from the heading \"Farm machinery\" and the instruction to stay back before passing."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "s12",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"do not\")",
      "text": "a driver SHOULD NOT pass farm machinery WHEN the driver is behind farm machinery UNTIL it is [?safe] to pass",
      "sources": [
        {
          "id": "m69",
          "quote": "Stay well back and do not pass until it is safe to do so."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "safe",
          "note": "No test is given for when passing farm machinery is safe."
        },
        {
          "code": "D",
          "span": "behind farm machinery",
          "note": "The situation is not explicitly stated in the sentence; it is inferred from the heading \"Farm machinery\" and the need to pass."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "s13",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Maintain\")",
      "text": "a driver SHOULD maintain a [?safe] following distance from a horse-drawn vehicle WHEN the driver is following a horse-drawn vehicle",
      "sources": [
        {
          "id": "m70",
          "quote": "Maintain a safe following distance and only pass when it is safe to do so."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "safe",
          "note": "No distance measure is given."
        }
      ],
      "links": [],
      "note": "The object \"horse-drawn vehicle\" comes from the passage heading."
    },
    {
      "id": "s14",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"only pass\")",
      "text": "a driver SHOULD NOT pass a horse-drawn vehicle UNLESS it is [?safe] to pass",
      "sources": [
        {
          "id": "m70",
          "quote": "Maintain a safe following distance and only pass when it is safe to do so."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "safe",
          "note": "No test is given for when passing is safe."
        }
      ],
      "links": [],
      "note": "\"only pass when safe\" is written as SHOULD NOT ... UNLESS; the object comes from the passage heading."
    },
    {
      "id": "s15",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"give\")",
      "text": "a driver SHOULD give [?as much distance between the driver's vehicle and the horse-drawn vehicle as possible] WHEN the driver is passing a horse-drawn vehicle BECAUSE passing [?too closely] could scare or startle the horse, causing it to change direction suddenly on the roadway",
      "sources": [
        {
          "id": "m71",
          "quote": "When passing, give as much distance between you and them as possible. Passing too closely could scare or startle the horse, causing it to change direction suddenly on the roadway."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "as much distance between the driver's vehicle and the horse-drawn vehicle as possible",
          "note": "No maximum distance or measure is given."
        },
        {
          "code": "J",
          "span": "too closely",
          "note": "No distance measure is given for close passing."
        }
      ],
      "links": [],
      "note": "\"them\" is interpreted as the horse-drawn vehicle from the heading, and \"the horse\" is the animal in it."
    }
  ]
}
